 * @description grd_resultList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_resultList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.loadCapital(r["bzProcsNo"], r["clmInstSeq"], r["comNm"], r["invstChgTpCd"], r["invstDd"], r["invstSaleShrs"], r["pershrInvstSaleAmt"], r["stkNm"], r["incdecRsn"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultList.oncellclick' });
    }
};

/**
 * @method
 * @name onload
 * @description onload 처리
 * @returns {void}
 * @hidden N
 */
scwin.onload = function () {
    try {
        scwin.form = (document.preListForm || { elements: [] });
        if (($c.util.getComponent('dma_RegisterReq').get('page')) > ($c.util.getComponent('dma_RegisterReq').get('billLstSaveStatCd'))) {
            return;
        }
        scwin.onloadDataSet();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil51050n.onload" });
    }
};

/**
 * @method
 * @name onloadDataSet
 * @description onload Data Set 처리
 * @returns {void}
 * @hidden N
 */
scwin.onloadDataSet = function () {
    /* empty */
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Register
 * @description Register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Register = async function () {
    const sbmOptions = {
        id: "tx_fn_Register",
        method: "post",
        action: "/listInvstg/listPrelmInvstgEtc.do",
        ref: "dma_RegisterReq",
        target: "dlt_resultList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

