};

/**
 * @method
 * @name prelistPageSearch
 * @description prelist Page Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.prelistPageSearch = async function () {
    const gongmo = $c.util.getComponent('dma_RegisterReq').get('gongMo');
    $c.util.getComponent('dma_RegisterReq').set('method', "listPrelmInvstgList");
    if (gongmo === "Y") {
        $c.util.getComponent('dma_RegisterReq').set('page', "konexGongsamo");
    } else {
        $c.util.getComponent('dma_RegisterReq').set('page', "konex");
    }
    await scwin.tx_fn_PrelistPageSearch();
};

